mapper.update:
UPDATE lunaerp_baseinfo_customer_contact
SET deleted = 0,
    updater = #{updater},
    update_time = #{updateTime}
WHERE customer_id = #{customerId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_baseinfo_customer_contact
WHERE customer_id = #{customerId}
  AND tenant_id = #{tenantId}
